SINA_SMART["hemato1-haemostasis"] = {"lecture":"hemato1-haemostasis","title":"Introduction to haemostasis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-haemostasis:e0","text":"Haemostasis: plug at the injury, fluid blood elsewhere.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haemostasis:e1","text":"Steps: vasoconstriction, platelet plug (primary), fibrin clot (secondary), fibrinolysis.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haemostasis:e2","text":"Bleeding: haemophilia, von Willebrand disease, thrombocytopenia.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haemostasis:e3","text":"Thrombosis: factor V Leiden, prothrombin mutation, protein C deficiency, cancer, sepsis.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haemostasis:e4","text":"Platelets: anucleate, 150-400 G/L, ~8-10 days, destroyed in spleen.","topic":"Platelets","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haemostasis:e5","text":"Megakaryocyte: endomitosis; ~2,000 platelets each; TPO from liver.","topic":"Platelets","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haemostasis:e6","text":"Receptors GPIb, GPIIb-IIIa, GPVI; α-granules (VWF, fibrinogen); dense granules (ADP, Ca²⁺, serotonin).","topic":"Platelets","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haemostasis:e7","text":"Endothelium thromboresistant; subendothelium thrombogenic (collagen, VWF, tissue factor).","topic":"Vessel wall","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haemostasis:e8","text":"VWF carries factor VIII and bridges platelets to collagen.","topic":"Vessel wall","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"9t745g":"a","1utfyu":"a","14uhz2n":"a","63nd0k":"a","143tgpr":"a","75bs7w":"a","1iovbjc":"a","j6y525":"a","1f0g5yi":"a","4d4r60":"a","jbfq6d":"a","1826yzv":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-haemostasis:e0":{"s":0,"u":["Haemostasis: plug at the injury, fluid blood elsewhere.","Haemostasis is the body's normal response to vessel injury: it forms a haemostatic plug at the site of damage and then keeps the blood fluid and clot-free elsewhere, dissolving the clot once healing starts.","Four overlapping steps: 1. vasoconstriction ; 2. platelet plug formation ( primary haemostasis ); 3. fibrin clot formation by the coagulation cascade converting fibrinogen to fibrin ( secondary haemostasis ); 4. fibrinolysis ."],"dp":[]},"hemato1-haemostasis:e1":{"s":0,"u":["Steps: vasoconstriction, platelet plug (primary), fibrin clot (secondary), fibrinolysis.","Four overlapping steps: 1. vasoconstriction ; 2. platelet plug formation ( primary haemostasis ); 3. fibrin clot formation by the coagulation cascade converting fibrinogen to fibrin ( secondary haemostasis ); 4. fibrinolysis .","Haemostasis is the body's normal response to vessel injury: it forms a haemostatic plug at the site of damage and then keeps the blood fluid and clot-free elsewhere, dissolving the clot once healing starts."],"dp":[]},"hemato1-haemostasis:e2":{"s":0,"u":["Bleeding: haemophilia, von Willebrand disease, thrombocytopenia.","Failure in one direction causes bleeding (haemophilia, von Willebrand disease, thrombocytopenia, leukaemia); in the other, thrombosis (inherited: factor V Leiden, prothrombin gene mutation, protein C deficiency; acquired: cancer, inflammatory bowel disease, sepsis), with stroke, DVT, pulmonary embolism or MI."],"dp":[]},"hemato1-haemostasis:e3":{"s":0,"u":["Thrombosis: factor V Leiden, prothrombin mutation, protein C deficiency, cancer, sepsis.","Failure in one direction causes bleeding (haemophilia, von Willebrand disease, thrombocytopenia, leukaemia); in the other, thrombosis (inherited: factor V Leiden, prothrombin gene mutation, protein C deficiency; acquired: cancer, inflammatory bowel disease, sepsis), with stroke, DVT, pulmonary embolism or MI."],"dp":[]},"hemato1-haemostasis:e4":{"s":1,"u":["Platelets: anucleate, 150-400 G/L, ~8-10 days, destroyed in spleen.","Small anucleate discs formed from the cytoplasm of megakaryocytes ; count 150,000-400,000/mm³ ; life span about 8-10 days ; destroyed in the spleen; about two thirds circulate and one third is held in the spleen ."],"dp":[]},"hemato1-haemostasis:e5":{"s":1,"u":["Megakaryocyte: endomitosis; ~2,000 platelets each; TPO from liver.","Regulation: thrombopoietin (TPO) , made by the liver.","Megakaryopoiesis : proliferation, then endomitosis (nuclear division without cell division, making a large polyploid cell), then cytoplasmic maturation; each megakaryocyte fragments into about 2,000 platelets ."],"dp":[]},"hemato1-haemostasis:e6":{"s":1,"u":["Receptors GPIb, GPIIb-IIIa, GPVI; α-granules (VWF, fibrinogen); dense granules (ADP, Ca²⁺, serotonin).","Structure: a phospholipid membrane (platelet factor 3, thromboxane production) carrying glycoprotein receptors (GPIb-IX, GPIIb-IIIa, GPVI) and antigens (ABO, HLA, HPA); an open canalicular system; a cytoskeleton; α-granules (von Willebrand factor, fibrinogen, platelet factor 4, β-thromboglobulin) and dense granules (ADP, ATP, calcium, serotonin)."],"dp":[]},"hemato1-haemostasis:e7":{"s":2,"u":["Endothelium thromboresistant; subendothelium thrombogenic (collagen, VWF, tissue factor).","The subendothelium is thrombogenic (collagen, von Willebrand factor, tissue factor that starts coagulation).","Von Willebrand factor (VWF) : a large multimeric protein from endothelium and megakaryocytes that circulates bound to factor VIII and bridges platelets (GPIb) to collagen."],"dp":[]},"hemato1-haemostasis:e8":{"s":2,"u":["VWF carries factor VIII and bridges platelets to collagen.","Von Willebrand factor (VWF) : a large multimeric protein from endothelium and megakaryocytes that circulates bound to factor VIII and bridges platelets (GPIb) to collagen.","The subendothelium is thrombogenic (collagen, von Willebrand factor, tissue factor that starts coagulation)."],"dp":[]}},"meta":{"9t745g":{"a":"recall","vg":"hemato1-haemostasis:e0/recall/1"},"1utfyu":{"a":"recall","vg":"hemato1-haemostasis:e0/recall/1"},"14uhz2n":{"a":"recall","vg":"hemato1-haemostasis:e1/recall/1"},"63nd0k":{"a":"recall","vg":"hemato1-haemostasis:e3/recall/1"},"143tgpr":{"a":"recall","vg":"hemato1-haemostasis:e5/recall/1"},"75bs7w":{"a":"recall","vg":"hemato1-haemostasis:e5/recall/2"},"1iovbjc":{"a":"recall","vg":"hemato1-haemostasis:e5/recall/3"},"j6y525":{"a":"recall","vg":"hemato1-haemostasis:e5/recall/4"},"1f0g5yi":{"a":"recall","vg":"hemato1-haemostasis:e6/recall/1"},"4d4r60":{"a":"recall","vg":"hemato1-haemostasis:e8/recall/1"},"jbfq6d":{"a":"recall","vg":"hemato1-haemostasis:e7/recall/1"},"1826yzv":{"a":"recall","vg":"hemato1-haemostasis:e4/recall/1"}},"explRev":"7835dc76b37f"};
